                        err = push_nsh(skb, key, nh);
                        break;
                }

                case OVS_ACTION_ATTR_POP_NSH:
                        err = pop_nsh(skb, key);
                        break;

                case OVS_ACTION_ATTR_METER:
                        if (ovs_meter_execute(dp, skb, key, nla_get_u32(a))) {
                                consume_skb(skb);
                                return 0;
                        }
                }

                if (unlikely(err)) {
                        kfree_skb(skb);
